//! The Ribbon citizen — generated by mobius_codegen.

use egui_citizen::citizen_panel;

use crate::state::{Chrome, RibbonCmd, Theme};

citizen_panel!(Ribbon, "ribbon",
    // Path B outbox for the `actions` signal — drained by the
    // app once per frame.
    outbox: Vec<RibbonCmd> = Vec::new(),
);

impl Ribbon {
    pub fn show(&mut self, ui: &mut egui::Ui, c: &Chrome, workspace: &mut crate::Workspace) {
        ui.add_space(3.0);
        let theme = c.theme.get();
        ui.horizontal(|ui| {
            ui.scope(|ui| {
                ui.spacing_mut().item_spacing.x = 0.0;
                let (brand_a, _) = theme.brand();
                ui.heading(egui::RichText::new("Workbench").size(20.0).strong().color(brand_a));
            });
            ui.separator();
            if ui.button("New").clicked() {
                self.outbox.push(RibbonCmd::New);
            }
            if ui.button("Open").clicked() {
                self.outbox.push(RibbonCmd::Open);
            }
            if ui.button("💾 Save").clicked() {
                self.outbox.push(RibbonCmd::Save);
            }
            ui.separator();
            if ui.button("⚙ Build").clicked() {
                self.outbox.push(RibbonCmd::Build);
            }
            if ui.button("⚡ Emit").clicked() {
                self.outbox.push(RibbonCmd::Emit);
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                ui.label(egui::RichText::new(c.clock.get()).monospace().color(theme.accent()));
                ui.separator();
                if ui.button(egui::RichText::new("ℹ About").color(theme.accent())).clicked() {
                    c.show_about.set(true);
                }
                let mut picked = c.theme.get();
                egui::ComboBox::from_id_salt("ribbon_theme")
                    .selected_text(format!("🎨 {}", picked.label()))
                    .show_ui(ui, |ui| {
                        for variant in Theme::ALL {
                            ui.selectable_value(&mut picked, variant, variant.label());
                        }
                    });
                if picked != c.theme.get() {
                    c.theme.set(picked);
                    picked.apply(ui.ctx());
                }
                workspace.perspectives_menu(ui);
            });
        });
    }
}
